B.abj=new A.n([B.G,"Forge unavailable. Sign in and retry later.",B.l,"Officina non disponibile. Accedi e riprova pi\xf9 tardi.",B.k,"Forja no disponible. Inicia sesi\xf3n e int\xe9ntalo m\xe1s tarde.",B.i,"\u935b\u51b6\u5834\u3092\u5229\u7528\u3067\u304d\u307e\u305b\u3093\u3002\u30ed\u30b0\u30a4\u30f3\u3057\u3066\u518d\u8a66\u884c\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\ub300\uc7a5\uac04\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ub85c\uadf8\uc778 \ud6c4 \ub2e4\uc2dc \uc2dc\ub3c4\ud558\uc138\uc694.",B.f,"\u953b\u9020\u6682\u4e0d\u53ef\u7528\uff0c\u8bf7\u767b\u5f55\u540e\u91cd\u8bd5\u3002",B.j,"Schmiede nicht verf\xfcgbar. Anmelden und sp\xe4ter erneut versuchen."],t.N)
B.aaY=new A.n([B.G,"Progress changed. Refresh before another attempt.",B.l,"Progressi cambiati. Aggiorna prima di riprovare.",B.k,"El progreso cambi\xf3. Actualiza antes de reintentar.",B.i,"\u9032\u884c\u72b6\u6cc1\u304c\u5909\u308f\u308a\u307e\u3057\u305f\u3002\u66f4\u65b0\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uc9c4\ud589 \uc0c1\ud669\uc774 \ubcc0\uacbd\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc0c8\ub85c\uace0\uce68\ud558\uc138\uc694.",B.f,"\u8fdb\u5ea6\u5df2\u53d8\u66f4\uff0c\u8bf7\u5237\u65b0\u540e\u91cd\u8bd5\u3002",B.j,"Fortschritt ge\xe4ndert. Vor erneutem Versuch aktualisieren."],t.N)
B.abt=new A.n([B.G,"Resolve your duplicate card first.",B.l,"Risolvi prima la carta duplicata.",B.k,"Resuelve primero la carta duplicada.",B.i,"\u5148\u306b\u91cd\u8907\u30ab\u30fc\u30c9\u3092\u51e6\u7406\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uba3c\uc800 \uc911\ubcf5 \uce74\ub4dc\ub97c \ucc98\ub9ac\ud558\uc138\uc694.",B.f,"\u8bf7\u5148\u5904\u7406\u91cd\u590d\u5361\u724c\u3002",B.j,"Zuerst die doppelte Karte bearbeiten."],t.N)
