B.ab6=new A.n([B.G,"Action failed. Try again.",B.l,"Operazione non riuscita. Riprova.",B.k,"La operaci\xf3n ha fallado. Reint\xe9ntalo.",B.i,"\u64cd\u4f5c\u306b\u5931\u6557\u3057\u307e\u3057\u305f\u3002\u518d\u8a66\u884c\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uc791\uc5c5\uc5d0 \uc2e4\ud328\ud588\uc2b5\ub2c8\ub2e4. \ub2e4\uc2dc \uc2dc\ub3c4\ud558\uc138\uc694.",B.f,"\u64cd\u4f5c\u5931\u8d25\uff0c\u8bf7\u91cd\u8bd5\u3002",B.j,"Vorgang fehlgeschlagen. Bitte erneut versuchen."],t.N)
B.abB=new A.n([B.G,"Check the name, description and emblem.",B.l,"Controlla nome, descrizione e stemma.",B.k,"Revisa el nombre, la descripci\xf3n y el emblema.",B.i,"\u540d\u524d\u3001\u8aac\u660e\u3001\u7d0b\u7ae0\u3092\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uc774\ub984, \uc124\uba85, \ubb38\uc7a5\uc744 \ud655\uc778\ud558\uc138\uc694.",B.f,"\u8bf7\u68c0\u67e5\u540d\u79f0\u3001\u63cf\u8ff0\u548c\u5fbd\u7ae0\u3002",B.j,"Pr\xfcfe Name, Beschreibung und Wappen."],t.N)
B.aaQ=new A.n([B.G,"This clan name is already taken.",B.l,"Questo nome \xe8 gi\xe0 utilizzato.",B.k,"Ese nombre ya est\xe1 en uso.",B.i,"\u3053\u306e\u540d\u524d\u306f\u4f7f\u7528\u3055\u308c\u3066\u3044\u307e\u3059\u3002",B.h,"\uc774\ubbf8 \uc0ac\uc6a9 \uc911\uc778 \uc774\ub984\uc785\ub2c8\ub2e4.",B.f,"\u8be5\u540d\u79f0\u5df2\u88ab\u4f7f\u7528\u3002",B.j,"Dieser Name ist bereits vergeben."],t.N)
B.abr=new A.n([B.G,"You already belong to a clan. Leave it before switching.",B.l,"Appartieni gi\xe0 a un clan. Lascialo prima di cambiarlo.",B.k,"Ya perteneces a un clan. Sal antes de cambiar.",B.i,"\u3059\u3067\u306b\u30af\u30e9\u30f3\u306b\u6240\u5c5e\u3057\u3066\u3044\u307e\u3059\u3002\u5909\u66f4\u3059\u308b\u306b\u306f\u8131\u9000\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uc774\ubbf8 \ud074\ub79c\uc5d0 \uac00\uc785\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \ud0c8\ud1f4\ud558\uc138\uc694.",B.f,"\u4f60\u5df2\u52a0\u5165\u6c0f\u65cf\uff0c\u8bf7\u5148\u9000\u51fa\u518d\u66f4\u6362\u3002",B.j,"Du geh\xf6rst bereits einem Clan an. Verlasse ihn zuerst."],t.N)
B.abb=new A.n([B.G,"You can create one clan per hour.",B.l,"Puoi creare un clan ogni ora.",B.k,"Puedes crear un clan por hora.",B.i,"\u30af\u30e9\u30f3\u4f5c\u6210\u306f1\u6642\u9593\u306b1\u56de\u307e\u3067\u3067\u3059\u3002",B.h,"\ud074\ub79c\uc740 \ud55c \uc2dc\uac04\uc5d0 \ud55c \ubc88 \uc0dd\uc131\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.",B.f,"\u6bcf\u5c0f\u65f6\u53ea\u80fd\u521b\u5efa\u4e00\u4e2a\u6c0f\u65cf\u3002",B.j,"Du kannst pro Stunde einen Clan gr\xfcnden."],t.N)
B.abn=new A.n([B.G,"Clan not found or dissolved.",B.l,"Clan non trovato o sciolto.",B.k,"Clan no encontrado o disuelto.",B.i,"\u30af\u30e9\u30f3\u304c\u898b\u3064\u304b\u3089\u306a\u3044\u304b\u89e3\u6563\u6e08\u307f\u3067\u3059\u3002",B.h,"\ud074\ub79c\uc744 \ucc3e\uc744 \uc218 \uc5c6\uac70\ub098 \ud574\uc0b0\ub418\uc5c8\uc2b5\ub2c8\ub2e4.",B.f,"\u6c0f\u65cf\u4e0d\u5b58\u5728\u6216\u5df2\u89e3\u6563\u3002",B.j,"Clan nicht gefunden oder aufgel\xf6st."],t.N)
B.ab2=new A.n([B.G,"Confirm before leaving your clan.",B.l,"Conferma prima di lasciare il clan.",B.k,"Confirma antes de salir del clan.",B.i,"\u8131\u9000\u3059\u308b\u524d\u306b\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\ud074\ub79c \ud0c8\ud1f4\ub97c \ud655\uc778\ud558\uc138\uc694.",B.f,"\u8bf7\u786e\u8ba4\u9000\u51fa\u6c0f\u65cf\u3002",B.j,"Best\xe4tige das Verlassen des Clans."],t.N)
B.aaO=new A.n([B.G,"Leave this clan? Leadership passes to the earliest member. If you are the last member, the clan will be dissolved.",B.l,"Vuoi lasciare il clan? Se sei la guida, passer\xe0 al membro iscritto da pi\xf9 tempo. Se sei l\u2019ultimo membro, il clan sar\xe0 sciolto.",B.k,"\xbfQuieres salir? El liderazgo pasar\xe1 al miembro m\xe1s antiguo. Si eres el \xfaltimo, el clan se disolver\xe1.",B.i,"\u8131\u9000\u3057\u307e\u3059\u304b\uff1f\u30ea\u30fc\u30c0\u30fc\u306f\u6700\u3082\u53e4\u3044\u30e1\u30f3\u30d0\u30fc\u306b\u5f15\u304d\u7d99\u304c\u308c\u3001\u6700\u5f8c\u306e\u30e1\u30f3\u30d0\u30fc\u306a\u3089\u89e3\u6563\u3057\u307e\u3059\u3002",B.h,"\ud0c8\ud1f4\ud558\uc2dc\uaca0\uc2b5\ub2c8\uae4c? \ub300\ud45c\ub294 \uac00\uc7a5 \uc624\ub798\ub41c \uba64\ubc84\uc5d0\uac8c \uc774\uc804\ub418\uba70 \ub9c8\uc9c0\ub9c9 \uba64\ubc84\ub77c\uba74 \ud074\ub79c\uc774 \ud574\uc0b0\ub429\ub2c8\ub2e4.",B.f,"\u786e\u5b9a\u9000\u51fa\u5417\uff1f\u65cf\u957f\u5c06\u8f6c\u4ea4\u7ed9\u6700\u65e9\u52a0\u5165\u7684\u6210\u5458\uff1b\u82e5\u4f60\u662f\u6700\u540e\u4e00\u4eba\uff0c\u6c0f\u65cf\u5c06\u89e3\u6563\u3002",B.j,"Clan verlassen? Die Leitung geht an das \xe4lteste Mitglied. Als letztes Mitglied l\xf6st du den Clan auf."],t.N)
