B.ae0=new A.n([B.l,"Confronta le carte e scegli quale tenere.",B.k,"Compara las cartas y elige cu\xe1l conservar.",B.i,"\u30ab\u30fc\u30c9\u3092\u6bd4\u8f03\u3057\u3001\u6b8b\u3059\u65b9\u3092\u9078\u3093\u3067\u304f\u3060\u3055\u3044\u3002",B.h,"\ub450 \uce74\ub4dc\ub97c \ube44\uad50\ud558\uace0 \ubcf4\uc720\ud560 \uce74\ub4dc\ub97c \uc120\ud0dd\ud558\uc138\uc694.",B.f,"\u6bd4\u8f83\u4e24\u5f20\u5361\u724c\uff0c\u7136\u540e\u9009\u62e9\u4fdd\u7559\u54ea\u5f20\u3002",B.j,"Vergleiche die Karten und w\xe4hle, welche du beh\xe4ltst."],t.N)
B.aed=new A.n([B.l,"Un nuovo campione entra nella tua collezione!",B.k,"\xa1Un nuevo campe\xf3n se une a tu colecci\xf3n!",B.i,"\u65b0\u3057\u3044\u82f1\u96c4\u304c\u30b3\u30ec\u30af\u30b7\u30e7\u30f3\u306b\u52a0\u308f\u308a\u307e\u3057\u305f\uff01",B.h,"\uc0c8\ub85c\uc6b4 \uc601\uc6c5\uc774 \uceec\ub809\uc158\uc5d0 \ucd94\uac00\ub418\uc5c8\uc2b5\ub2c8\ub2e4!",B.f,"\u65b0\u82f1\u96c4\u52a0\u5165\u4e86\u4f60\u7684\u6536\u85cf\uff01",B.j,"Ein neuer Held erg\xe4nzt deine Sammlung!"],t.N)
