B.adM=new A.n([B.l,"Accedi per scegliere il tuo nome definitivo.",B.k,"Inicia sesi\xf3n para elegir tu nombre definitivo.",B.i,"\u30ed\u30b0\u30a4\u30f3\u3057\u3066\u540d\u524d\u3092\u4e00\u5ea6\u3060\u3051\u8a2d\u5b9a\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\ub85c\uadf8\uc778\ud558\uc5ec \uc601\uad6c \uc774\ub984\uc744 \uc120\ud0dd\ud558\uc138\uc694.",B.f,"\u767b\u5f55\u4ee5\u9009\u62e9\u6c38\u4e45\u540d\u79f0\u3002",B.j,"Anmelden, um den dauerhaften Namen zu w\xe4hlen."],t.N)
B.adf=new A.n([B.l,"Scegli un nome valido (3\u201320 caratteri).",B.k,"Elige un nombre v\xe1lido (3\u201320 caracteres).",B.i,"3\uff5e20\u6587\u5b57\u306e\u6709\u52b9\u306a\u540d\u524d\u3092\u9078\u629e\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uc720\ud6a8\ud55c \uc774\ub984\uc744 \uc120\ud0dd\ud558\uc138\uc694 (3~20\uc790).",B.f,"\u8bf7\u9009\u62e9\u6709\u6548\u540d\u79f0\uff083\u201320\u4e2a\u5b57\u7b26\uff09\u3002",B.j,"W\xe4hle einen g\xfcltigen Namen (3\u201320 Zeichen)."],t.N)
