B.aeM=new A.n([B.l,"Nessun banner evento attivo. Probabilit\xe0 ed eroi in evidenza appariranno qui quando sar\xe0 configurato un evento.",B.k,"No hay ning\xfan banner de evento activo. Las probabilidades y h\xe9roes destacados aparecer\xe1n aqu\xed cuando se configure un evento.",B.i,"\u958b\u50ac\u4e2d\u306e\u30a4\u30d9\u30f3\u30c8\u53ec\u559a\u306f\u3042\u308a\u307e\u305b\u3093\u3002\u30a4\u30d9\u30f3\u30c8\u8a2d\u5b9a\u6642\u306b\u78ba\u7387\u3068\u6ce8\u76ee\u82f1\u96c4\u304c\u8868\u793a\u3055\u308c\u307e\u3059\u3002",B.h,"\uc9c4\ud589 \uc911\uc778 \uc774\ubca4\ud2b8 \ubc30\ub108\uac00 \uc5c6\uc2b5\ub2c8\ub2e4. \uc774\ubca4\ud2b8\uac00 \uc124\uc815\ub418\uba74 \ud655\ub960\uacfc \ucd94\ucc9c \uc601\uc6c5\uc774 \ud45c\uc2dc\ub429\ub2c8\ub2e4.",B.f,"\u5f53\u524d\u6ca1\u6709\u6d3b\u52a8\u5361\u6c60\u3002\u914d\u7f6e\u6d3b\u52a8\u540e\uff0c\u6982\u7387\u548c\u7cbe\u9009\u82f1\u96c4\u4f1a\u663e\u793a\u5728\u8fd9\u91cc\u3002",B.j,"Kein Event-Banner aktiv. Raten und vorgestellte Helden erscheinen hier, sobald ein Event eingerichtet ist."],t.N)
B.af9=new A.n([B.l,"Costo: 300 Shard o una carica gratis.",B.k,"Coste: 300 Shards o una carga gratis.",B.i,"\u30b3\u30b9\u30c8\uff1a300\u30b7\u30e3\u30fc\u30c9\u307e\u305f\u306f\u7121\u6599\u30c1\u30e3\u30fc\u30b81\u56de\u3002",B.h,"\ube44\uc6a9: \uc0e4\ub4dc 300\uac1c \ub610\ub294 \ubb34\ub8cc \ucda9\uc804 1\ud68c.",B.f,"\u82b1\u8d39\uff1a300\u788e\u7247\u6216\u4e00\u6b21\u514d\u8d39\u5145\u80fd\u3002",B.j,"Kosten: 300 Shards oder eine Gratisladung."],t.N)
B.ad9=new A.n([B.l,"2 cariche gratis; ciascuna si ricarica 12 ore dopo l\u2019uso.",B.k,"2 cargas gratis; cada una se recarga 12 horas despu\xe9s de usarla.",B.i,"\u7121\u6599\u30c1\u30e3\u30fc\u30b8\u306f2\u56de\u5206\u3002\u4f7f\u7528\u5f8c12\u6642\u9593\u3067\u54041\u56de\u5fa9\u3057\u307e\u3059\u3002",B.h,"\ubb34\ub8cc \ucda9\uc804 2\ud68c; \uc0ac\uc6a9 \ud6c4 \uac01\uac01 12\uc2dc\uac04 \ub4a4 \ucda9\uc804\ub429\ub2c8\ub2e4.",B.f,"2\u6b21\u514d\u8d39\u5145\u80fd\uff1b\u6bcf\u6b21\u4f7f\u7528\u540e12\u5c0f\u65f6\u6062\u590d\u3002",B.j,"2 Gratisladungen; jede l\xe4dt sich 12 Stunden nach Nutzung auf."],t.N)
